/* =================== QUESTION BANK ===================
   ty: mc (o = options, a = index) · tf (a = true/false) · fill (a = accepted answers) · order (o = items in the right order) · match (o = [left, right] pairs)
   d: e = easy, m = medium, h = hard · tags: subnet, trace, beep, port, binary, predict ...
   why = why the answer is right · trap = the likely mistake and how to fix it */
const BANK = [
 /* ---------- NTWK ---------- */
 {id:"n1-01",t:"n1",d:"e",ty:"mc",q:"Every computer in the UTT lab plugs into one central switch. Which topology is this?",o:["Bus","Star","Ring","Mesh"],a:1,
  why:"In a star topology every device has its own cable to one central device, usually a switch.",trap:"Bus uses one shared backbone cable that every device taps into. If you see a central box, think star."},
 {id:"n1-02",t:"n1",d:"e",ty:"tf",q:"In a peer-to-peer network there is no dedicated server: each computer can both share and use resources.",a:true,
  why:"That's the definition of peer-to-peer. Each peer is equal, like friends lending each other notes.",trap:"Client/server is the one with a dedicated server that the other computers (clients) request things from."},
 {id:"n1-03",t:"n1",d:"m",ty:"mc",q:"A network links several office buildings across one city, such as Port of Spain. What type of network is it?",o:["PAN","LAN","MAN","WAN"],a:2,
  why:"A MAN (metropolitan area network) covers a town or city. A LAN covers one building or campus; a WAN covers countries or regions.",trap:"Students jump to WAN for anything bigger than a building. WAN is for very large distances, like Trinidad to Tobago or Miami."},
 {id:"n1-04",t:"n1",d:"m",ty:"mc",q:"Which topology connects every device directly to every other device, giving the most redundant paths?",o:["Full mesh","Star","Bus","Ring"],a:0,
  why:"In a full mesh each device has a link to every other device, so if one link fails traffic can take another path.",trap:"A ring has only two neighbours per device. Mesh = many paths, like a spider's web."},
 {id:"n2-01",t:"n2",d:"m",ty:"order",q:"Put the PDU names in encapsulation order, from what the application creates down to what goes on the wire.",o:["Data","Segment","Packet","Frame","Bits"],
  why:"Going down the layers: Data (layers 7–5) → Segment (Transport, 4) → Packet (Network, 3) → Frame (Data Link, 2) → Bits (Physical, 1).",trap:"Mixing up packet and frame is the usual slip. Packet = layer 3 (IP addresses). Frame = layer 2 (MAC addresses)."},
 {id:"n2-02",t:"n2",d:"e",ty:"mc",q:"At which OSI layer does a router make its decisions?",o:["Layer 1 – Physical","Layer 2 – Data Link","Layer 3 – Network","Layer 4 – Transport"],a:2,
  why:"Routers read IP addresses and choose the best path between networks. IP addressing lives at layer 3, the Network layer.",trap:"Switches are layer 2 (MAC addresses). Routers are layer 3 (IP addresses)."},
 {id:"n2-03",t:"n2",d:"m",ty:"match",q:"Match each OSI layer to its PDU.",o:[["Transport","Segment"],["Network","Packet"],["Data Link","Frame"],["Physical","Bits"]],
  why:"Transport → Segment, Network → Packet, Data Link → Frame, Physical → Bits. Memory aid: Some People Fear Birthdays.",trap:"Remember the order top-down: Segment, Packet, Frame, Bits."},
 {id:"n2-04",t:"n2",d:"m",ty:"mc",q:"The TCP/IP model's Application layer covers which OSI layers?",o:["Layer 7 only","Layers 5, 6 and 7","Layers 1 and 2","Layers 3 and 4"],a:1,
  why:"TCP/IP squeezes OSI's Session (5), Presentation (6) and Application (7) layers into one Application layer.",trap:"OSI has 7 layers and TCP/IP has 4, so some OSI layers must be grouped together."},
 {id:"n3-01",t:"n3",d:"m",ty:"mc",q:"In the T568B standard, what colour wire goes in pin 1?",o:["White/orange","White/green","Orange","Blue"],a:0,
  why:"T568B order: 1 white/orange, 2 orange, 3 white/green, 4 blue, 5 white/blue, 6 green, 7 white/brown, 8 brown.",trap:"White/green is pin 1 in T568A. The two standards swap the orange and green pairs."},
 {id:"n3-02",t:"n3",d:"e",ty:"mc",q:"What is the maximum length of a single UTP Ethernet cable run?",o:["10 m","100 m","500 m","2 km"],a:1,
  why:"Copper twisted-pair Ethernet (e.g. Cat5e, Cat6) is limited to 100 metres per run before the signal gets too weak.",trap:"Longer distances need fibre or a switch/repeater in between."},
 {id:"n3-03",t:"n3",d:"m",ty:"mc",q:"Which cable would you traditionally use to connect a PC to a switch?",o:["Crossover","Straight-through","Rollover","Coaxial"],a:1,
  why:"Different types of device (PC ↔ switch) use a straight-through cable: the same standard on both ends.",trap:"Crossover was for LIKE devices (PC ↔ PC, switch ↔ switch). Many modern ports auto-detect (Auto-MDIX), but exams still expect this rule."},
 {id:"n4-01",t:"n4",d:"m",ty:"mc",q:"Which Wi-Fi standard works ONLY in the 5 GHz band?",o:["802.11a","802.11b","802.11g","802.11n"],a:0,
  why:"802.11a uses 5 GHz only. 802.11b and g use 2.4 GHz. 802.11n can use both.",trap:"Students think 'a' must be the oldest and slowest 2.4 GHz one. It's 5 GHz, up to 54 Mbps."},
 {id:"n4-02",t:"n4",d:"e",ty:"mc",q:"Which wireless security option is the newest and strongest?",o:["WEP","WPA","WPA2","WPA3"],a:3,
  why:"WPA3 is the newest standard with the strongest protection. WEP is old and easily cracked.",trap:"Never choose WEP on an exam as 'secure'. It's the weakest."},
 {id:"n5-01",t:"n5",d:"e",ty:"mc",q:"Which device learns MAC addresses and sends each frame only to the port where the destination is?",o:["Hub","Switch","Router","Repeater"],a:1,
  why:"A switch keeps a MAC address table, like an office receptionist who knows exactly which desk everyone sits at.",trap:"A hub repeats every signal out of every port, like shouting across the whole office."},
 {id:"n5-02",t:"n5",d:"e",ty:"mc",q:"You need to join a fibre-optic link to a copper Ethernet switch port. Which device do you use?",o:["Bridge","Access point","Media converter","Modem"],a:2,
  why:"A media converter changes the signal from one type of media (fibre/light) to another (copper/electricity).",trap:"A bridge joins two network segments; it doesn't change the type of cable."},
 {id:"n6-01",t:"n6",d:"e",ty:"fill",q:"Convert the binary octet 11000000 to decimal.",a:["192"],tags:["binary"],
  why:"Place values: 128 64 32 16 8 4 2 1. The two 1s are 128 + 64 = 192.",trap:"Start from the left with 128, not 1."},
 {id:"n6-02",t:"n6",d:"m",ty:"mc",q:"How many usable host addresses are in the network 192.168.10.0/26?",o:["64","62","30","254"],a:1,tags:["subnet"],
  why:"/26 leaves 32 − 26 = 6 host bits. 2⁶ = 64 addresses, minus 2 (network and broadcast) = 62 usable hosts.",trap:"64 forgets to subtract the network and broadcast addresses: usable hosts = 2ⁿ − 2."},
 {id:"n6-03",t:"n6",d:"h",ty:"mc",q:"What is the broadcast address of the subnet that contains 192.168.1.70/27?",o:["192.168.1.64","192.168.1.95","192.168.1.127","192.168.1.255"],a:1,tags:["subnet"],
  why:"/27 → block size 32. Subnets start at .0, .32, .64, .96. 70 is in the .64 subnet, which runs .64 to .95. The broadcast is the last address: .95.",trap:"192.168.1.64 is the network address (first). The broadcast is the LAST address before the next subnet starts (.96 − 1 = .95)."},
 {id:"n6-04",t:"n6",d:"m",ty:"mc",q:"A laptop shows the IP address 169.254.12.7. What does this usually mean?",o:["It's using the loopback address","It couldn't get an address from a DHCP server","It has a public IP address","It's connected to a WAN"],a:1,
  why:"169.254.x.x is APIPA. Windows gives itself one of these when it asks for a DHCP address and nobody answers.",trap:"Loopback is 127.0.0.1. APIPA is the 'I asked for an address and got no reply' sign."},
 {id:"n6-05",t:"n6",d:"m",ty:"tf",q:"172.20.5.1 is a private IP address.",a:true,
  why:"The private ranges are 10.0.0.0/8, 172.16.0.0 to 172.31.255.255 (172.16.0.0/12) and 192.168.0.0/16. 172.20 falls inside 172.16–172.31.",trap:"Not every 172.x address is private, only 172.16 to 172.31."},
 {id:"n6-06",t:"n6",d:"e",ty:"fill",q:"Write the subnet mask for /24 in dotted decimal.",a:["255.255.255.0"],tags:["subnet"],
  why:"/24 means 24 ones: 11111111.11111111.11111111.00000000 = 255.255.255.0.",trap:"Each group of 8 ones is 255."},
 {id:"n7-01",t:"n7",d:"e",ty:"mc",q:"Which of these is the largest WAN in the world?",o:["The UTT campus network","The internet","A home Wi-Fi network","A Bluetooth headset link"],a:1,
  why:"The internet is a huge WAN made of many connected networks spanning the whole planet.",trap:"A campus is a LAN (or MAN if spread across a city). Bluetooth is a PAN."},
 {id:"n8-01",t:"n8",d:"e",ty:"mc",q:"You install a new router. What's the FIRST hardening step?",o:["Enable every service","Change the default admin password","Leave remote management on","Turn off the firewall"],a:1,
  why:"Default passwords are published online, so anyone could log in. Changing them is step one of device hardening.",trap:"Hardening means turning things OFF and locking them down, not switching more on."},
 {id:"n9-01",t:"n9",d:"m",ty:"order",q:"Put the troubleshooting methodology steps in order.",o:["Identify the problem","Establish a theory of probable cause","Test the theory","Establish a plan of action","Implement the solution or escalate","Verify full functionality","Document findings"],
  why:"Identify → theory → test → plan → implement → verify → document. Documenting comes LAST so the next technician can learn from it.",trap:"Don't jump straight to fixing. You must identify the problem and test a theory first."},
 {id:"n9-02",t:"n9",d:"e",ty:"mc",q:"Which Windows command shows a PC's IP address, subnet mask and default gateway?",o:["ping","ipconfig","tracert","nslookup"],a:1,
  why:"ipconfig shows the IP settings. ipconfig /all shows even more, like the MAC address and DNS servers.",trap:"ping tests whether another device replies; it doesn't show your own settings."},
 {id:"n9-03",t:"n9",d:"m",ty:"mc",q:"Which tool helps you find which cable at the patch panel goes to a wall jack?",o:["Crimper","Toner probe","Punch-down tool","Loopback plug"],a:1,
  why:"A toner sends a tone down the cable and the probe beeps when you touch the right one at the other end.",trap:"A crimper attaches RJ45 plugs; a punch-down tool seats wires into a patch panel."},
 {id:"n9-04",t:"n9",d:"e",ty:"mc",q:"Which port does DNS use?",o:["25","53","80","443"],a:1,tags:["port"],
  why:"DNS uses port 53. Memory aid: DNS turns names into numbers, and 53 is the number.",trap:"25 is SMTP (email sending), 80 is HTTP, 443 is HTTPS."},

 /* ---------- LOGC ---------- */
 {id:"l1-01",t:"l1",d:"e",ty:"mc",q:"In which stage of the program development life cycle do you draw the flowchart?",o:["Analysis","Design","Coding","Testing"],a:1,
  why:"Design is where you plan the solution: the algorithm, flowchart or pseudocode, before writing any code.",trap:"Analysis is about understanding the problem (inputs, outputs, formulas), not drawing the solution yet."},
 {id:"l2-01",t:"l2",d:"e",ty:"mc",q:"Problem: 'Read the length and width of a room, then display its area.' What is the OUTPUT?",o:["Length","Width","Area","Length × width formula"],a:2,
  why:"The output is what the program displays: the area. Length and width are inputs; area = length × width is the process.",trap:"The formula belongs in the Process column of the IPO chart, not the Output."},
 {id:"l3-01",t:"l3",d:"e",ty:"match",q:"Match each flowchart symbol to its job.",o:[["Oval / rounded rectangle","Start or stop"],["Parallelogram","Input or output"],["Rectangle","Process (calculation)"],["Diamond","Decision (yes/no)"]],
  why:"Terminator = oval, input/output = parallelogram, process = rectangle, decision = diamond.",trap:"Input and output share the same parallelogram symbol."},
 {id:"l4-01",t:"l4",d:"e",ty:"mc",q:"What does this print?",code:"print(7 // 2)",o:["3.5","3","4","1"],a:1,tags:["predict"],
  why:"// is floor division: it divides and drops the decimal part. 7 // 2 = 3.",trap:"3.5 is what / gives. 1 is 7 % 2 (the remainder)."},
 {id:"l4-02",t:"l4",d:"m",ty:"mc",q:"What does this print?",code:"print('5' + '3')",o:["8","53","'5' + '3'","An error"],a:1,tags:["predict"],
  why:"'5' and '3' are strings (text). + joins strings together, so the result is 53.",trap:"Quotes make it text. To add numbers you'd need int('5') + int('3')."},
 {id:"l4-03",t:"l4",d:"m",ty:"mc",q:"age = input('Age: ') — what data type is age?",o:["int","float","str","bool"],a:2,
  why:"input() ALWAYS returns a string, even if the user types a number.",trap:"To do maths you must convert it: age = int(input('Age: '))."},
 {id:"l4-04",t:"l4",d:"m",ty:"fill",q:"What does print(2 + 3 * 4) display?",a:["14"],tags:["predict"],
  why:"Multiplication happens before addition: 3 * 4 = 12, then 2 + 12 = 14.",trap:"Working left to right gives 20. Use BODMAS: brackets, powers, × and ÷, then + and −."},
 {id:"l5-01",t:"l5",d:"h",ty:"mc",q:"What does this print?",code:"x = 10\nif x > 5:\n    print('A')\nelif x > 8:\n    print('B')\nelse:\n    print('C')",o:["A","B","A and B","C"],a:0,tags:["predict"],
  why:"Python checks from the top and stops at the first True condition. x > 5 is True, so it prints A and skips the rest.",trap:"x > 8 is also true, but it's never reached. Put the most specific (biggest) condition first."},
 {id:"l5-02",t:"l5",d:"e",ty:"tf",q:"In Python, = is used to compare two values.",a:false,
  why:"= assigns a value to a variable. == compares two values and gives True or False.",trap:"if x = 5: is a syntax error. Write if x == 5:"},
 {id:"l6-01",t:"l6",d:"m",ty:"mc",q:"What does this print?",code:"for i in range(1, 4):\n    print(i, end=' ')",o:["1 2 3 4","1 2 3","0 1 2 3","2 3 4"],a:1,tags:["predict"],
  why:"range(1, 4) starts at 1 and STOPS BEFORE 4, so you get 1 2 3.",trap:"The stop value is never included. That's the classic off-by-one mistake."},
 {id:"l6-02",t:"l6",d:"m",ty:"mc",q:"Why does this loop never end?",code:"n = 0\nwhile n < 3:\n    print(n)",o:["n starts at 0","The condition should use <=","n is never updated inside the loop","print() stops loops"],a:2,
  why:"n stays 0 forever, so n < 3 is always True. Add n = n + 1 inside the loop.",trap:"Every while loop needs a line inside that moves the variable towards making the condition False."},
 {id:"l6-03",t:"l6",d:"m",ty:"fill",q:"What does this print?",code:"total = 0\nfor i in range(1, 4):\n    total = total + i\nprint(total)",a:["6"],tags:["predict"],
  why:"i takes 1, 2, 3. total goes 0 → 1 → 3 → 6.",trap:"Remember range(1, 4) stops before 4, so 4 is not added."},
 {id:"l7-01",t:"l7",d:"m",ty:"mc",q:"In a sentinel-controlled loop, why do we read the first value BEFORE the loop?",o:["To make the loop faster","So the while condition has a value to test the first time","Because Python requires two input() calls","To skip the first value"],a:1,
  why:"This is the priming read. The while condition needs a real value to check before the loop starts.",trap:"Without the priming read, the variable doesn't exist yet when the condition is tested."},
 {id:"l7-02",t:"l7",d:"h",ty:"mc",q:"Marks are entered until -1. What's wrong with this?",code:"total = 0\nmark = int(input())\nwhile mark != -1:\n    mark = int(input())\n    total = total + mark",o:["Nothing","The first mark is skipped and the -1 is added to the total","It never stops","total should start at 1"],a:1,
  why:"The new value is read BEFORE adding, so the first mark is lost and the sentinel -1 gets added. Add first, then read the next value at the END of the loop.",trap:"Processing the sentinel by mistake is a top exam error. Order inside the loop: process, then read next."},

 {id:"l1-02",t:"l1",d:"e",ty:"mc",q:"What is the main deliverable of the ANALYSIS stage?",o:["Source code","An IPO chart (inputs, processing, outputs)","A user guide","Test results"],a:1,
  why:"Analysis is about understanding the problem, so it produces the problem statement and IPO chart.",trap:"Source code comes from coding; test results from testing; the user guide from deployment."},
 {id:"l1-03",t:"l1",d:"e",ty:"order",q:"Put the stages of the program development life cycle in order.",o:["Analysis","Design","Coding","Testing","Deployment","Maintenance"],
  why:"Understand it, plan it, write it, check it, hand it over, keep it going.",trap:"Design (planning) always comes before coding. Never code before you've planned."},
 {id:"l1-04",t:"l1",d:"m",ty:"match",q:"Match each type of error to an example.",o:[["Syntax error","print('Hi' with a missing bracket"],["Runtime error","int('abc') crashes while running"],["Logic error","Wrong average shown, no error message"]],
  why:"Syntax = breaks the language rules so it won't start. Runtime = crashes part-way. Logic = runs but gives the wrong answer.",trap:"A wrong answer with no error message is ALWAYS a logic error."},
 {id:"l1-05",t:"l1",d:"e",ty:"tf",q:"Maintenance only happens when a program has bugs.",a:false,
  why:"Maintenance also covers adding new features and updating the program when things change (like a new VAT rate).",trap:"Think of maintenance as 'keeping it useful', not just 'fixing it'."},
 {id:"l1-06",t:"l1",d:"m",ty:"mc",q:"The VAT rate changes, so a programmer updates an existing billing program that people already use. Which stage is this?",o:["Analysis","Coding","Testing","Maintenance"],a:3,
  why:"Changing a program that's already in use is maintenance.",trap:"Even though code is being changed, the program is already deployed, so it's maintenance (which then loops back through the cycle)."},
 {id:"l1-07",t:"l1",d:"e",ty:"mc",q:"Debugging (finding and fixing errors) happens mainly in which stage?",o:["Analysis","Design","Testing","Deployment"],a:2,
  why:"In testing you run the program with test data, spot errors and fix them.",trap:"Analysis and design happen before there's any code to debug."},

 {id:"l2-02",t:"l2",d:"e",ty:"mc",q:"Problem: 'Read a student's three test marks and display their average.' What are the INPUTS?",o:["The average","The three test marks","average = (m1 + m2 + m3) / 3","Display the average"],a:1,
  why:"Inputs are what the user enters: the three marks.",trap:"The average is the output and the formula is the processing."},
 {id:"l2-03",t:"l2",d:"m",ty:"fill",q:"Using f = c × 9 / 5 + 32, what is 30 °C in Fahrenheit?",a:["86","86.0"],
  why:"30 × 9 = 270, 270 / 5 = 54, 54 + 32 = 86.",trap:"Multiply and divide BEFORE adding the 32."},
 {id:"l2-04",t:"l2",d:"e",ty:"match",q:"'Read the hours worked and display the pay at $25 an hour.' Match each item to its IPO column.",o:[["hours worked","Input"],["pay = hours × 25","Process"],["pay","Output"]],
  why:"The user gives the hours (input), the program works out the pay (process) and shows it (output).",trap:"$25 is a fixed rate given in the problem, so it isn't an input."},
 {id:"l2-05",t:"l2",d:"m",ty:"mc",q:"Which formula correctly finds the average of a, b and c?",o:["a + b + c / 3","(a + b + c) / 3","a + b + c * 3","(a + b + c) * 3"],a:1,
  why:"Add all three first (brackets), then divide by how many there are.",trap:"Without brackets, only c is divided by 3 because ÷ is done before +."},
 {id:"l2-06",t:"l2",d:"m",ty:"tf",q:"In 'Read the price of an item and calculate VAT at 12.5%', the 12.5% is an input.",a:false,
  why:"12.5% is given in the problem, so it's a fixed value used in processing. Only the price is input.",trap:"An input is something the user types when the program runs."},
 {id:"l2-07",t:"l2",d:"e",ty:"order",q:"Put the main steps for the VAT problem in order.",o:["Read the price","Calculate VAT = price × 0.125","Calculate total = price + VAT","Display the VAT and total"],
  why:"Get the inputs, do the processing, then display the outputs.",trap:"You can't calculate the total until VAT has been worked out."},

 {id:"l3-02",t:"l3",d:"e",ty:"mc",q:"Which flowchart symbol has two exits labelled Yes and No?",o:["Oval","Parallelogram","Rectangle","Diamond"],a:3,
  why:"The diamond is the decision symbol: a yes/no question with two ways out.",trap:"Every other symbol has just one arrow leaving it."},
 {id:"l3-03",t:"l3",d:"m",ty:"mc",q:"What's wrong with this flowchart?",fc:{n:[["s","term","Start",0],["i","io","Input length, width",1],["o","io","Output area",2],["p","proc","area = length × width",3],["e","term","Stop",4]],e:"chain"},
  o:["Nothing, it's correct","The area is output before it's calculated","Input should be in a rectangle","It needs a decision"],a:1,tags:["fixflow"],
  why:"The order must be Input → Process → Output. Here 'Output area' comes before area is worked out.",trap:"Swap the two middle steps: calculate area first, then output it."},
 {id:"l3-04",t:"l3",d:"m",ty:"mc",q:"Which shape in this flowchart is the wrong symbol?",fc:{n:[["s","term","Start",0],["i","proc","Input mark",1],["p","proc","bonus = mark + 5",2],["o","io","Output bonus",3],["e","term","Stop",4]],e:"chain"},
  o:["Start","Input mark","bonus = mark + 5","Output bonus"],a:1,tags:["fixflow"],
  why:"Input goes in a parallelogram, but 'Input mark' is drawn as a rectangle (the process symbol).",trap:"Rectangles are only for calculations and assignments."},
 {id:"l3-05",t:"l3",d:"e",ty:"order",q:"Build the flowchart: put these shapes in order to find the average of three marks.",o:["Start","Input m1, m2, m3","average = (m1 + m2 + m3) / 3","Output average","Stop"],tags:["buildflow"],
  why:"Start, get the inputs, calculate, show the result, stop.",trap:"Output always comes after the calculation it shows."},
 {id:"l3-06",t:"l3",d:"e",ty:"tf",q:"A flowchart can have two Start symbols.",a:false,
  why:"An algorithm begins in one place, so there's exactly one Start (and normally one Stop).",trap:"If paths split at a decision, they join again before Stop."},
 {id:"l3-07",t:"l3",d:"e",ty:"mc",q:"In a flowchart with SEQUENTIAL logic…",o:["Steps happen one after another with no decisions","Steps repeat until a condition is false","A diamond chooses between two paths","Steps can happen in any order"],a:0,
  why:"Sequence means straight down: each step once, in order.",trap:"Choosing between paths is selection; repeating is repetition (loops)."},

 {id:"l4-05",t:"l4",d:"m",ty:"mc",q:"What does this print?",code:"print(10 / 2)",o:["5","5.0","2","10/2"],a:1,tags:["predict"],
  why:"/ always gives a float (a decimal), even when it divides exactly, so 10 / 2 is 5.0.",trap:"Use // if you want the whole number 5."},
 {id:"l4-06",t:"l4",d:"e",ty:"fill",q:"What does this print?",code:"print(2 ** 3)",a:["8"],tags:["predict"],
  why:"** means 'to the power of': 2 × 2 × 2 = 8.",trap:"It's not 2 × 3 = 6."},
 {id:"l4-07",t:"l4",d:"e",ty:"mc",q:"Which is a valid Python variable name?",o:["2nd_mark","total marks","total_marks","class"],a:2,
  why:"Names may use letters, digits and underscores, but can't start with a digit, can't have spaces and can't be a keyword.",trap:"'class' is a Python keyword, so it can't be used as a variable name."},
 {id:"l4-08",t:"l4",d:"m",ty:"fill",q:"What does this print?",code:"x = 5\nx = x * 2\nx = x + 1\nprint(x)",a:["11"],tags:["predict"],
  why:"x goes 5 → 10 → 11. Each line uses the value x has at that moment.",trap:"Work line by line; don't use the starting value 5 every time."},
 {id:"l4-09",t:"l4",d:"h",ty:"mc",q:"She types 50. What is printed on the last line?",code:"price = input('Price: ')\ntotal = price * 2\nprint(total)",in:["50"],o:["100","5050","50 * 2","An error"],a:1,tags:["predict"],
  why:"input() gives the text '50'. Multiplying text by 2 repeats it: '5050'.",trap:"Convert first: price = int(input('Price: ')) would give 100."},
 {id:"l4-10",t:"l4",d:"m",ty:"mc",q:"What does this print?",code:"print(20 - 6 / 2)",o:["7.0","17.0","17","7"],a:1,tags:["predict"],
  why:"Division first: 6 / 2 = 3.0, then 20 − 3.0 = 17.0. It's a float because / was used.",trap:"Working left to right (20 − 6 = 14, ÷ 2 = 7) ignores the order of operations."},
 {id:"l4-11",t:"l4",d:"e",ty:"tf",q:"Python ignores everything after # on a line when the program runs.",a:true,
  why:"# starts a comment, a note for people reading the code.",trap:"A # inside quotes, like '#1', is just text, not a comment."},
 {id:"l4-12",t:"l4",d:"m",ty:"fill",q:"What does this print?",code:"print(17 // 5)",a:["3"],tags:["predict"],
  why:"// is floor division: 17 ÷ 5 = 3.4, and the decimal part is dropped, giving 3.",trap:"17 % 5 would give the remainder, 2."},

 {id:"l5-03",t:"l5",d:"m",ty:"mc",q:"What does this print?",code:"x = 7\nprint(x > 5 and x < 6)",o:["True","False","7","An error"],a:1,tags:["predict"],
  why:"x > 5 is True but x < 6 is False. 'and' needs BOTH to be True, so the answer is False.",trap:"With 'or' it would be True."},
 {id:"l5-04",t:"l5",d:"e",ty:"match",q:"Match each operator to its meaning.",o:[["==","is equal to"],["!=","is not equal to"],[">=","is greater than or equal to"],["<","is less than"]],
  why:"== compares; != means not equal; >= includes the number itself; < is strictly less than.",trap:"= on its own stores a value; it doesn't compare."},
 {id:"l5-05",t:"l5",d:"m",ty:"mc",q:"What does this print?",code:"mark = 65\nif mark >= 80:\n    print('A')\nelif mark >= 65:\n    print('B')\nelif mark >= 50:\n    print('C')\nelse:\n    print('F')",o:["A","B","C","B and C"],a:1,tags:["predict"],
  why:"65 >= 80 is False; 65 >= 65 is True, so it prints B and skips the rest.",trap:">= includes the number itself, so 65 counts as 'at least 65'."},
 {id:"l5-06",t:"l5",d:"h",ty:"mc",q:"What does this print?",code:"age = 20\nhas_id = False\nif age >= 18:\n    if has_id:\n        print('Come in')\n    else:\n        print('Show ID')\nelse:\n    print('Too young')",o:["Come in","Show ID","Too young","Nothing"],a:1,tags:["predict"],
  why:"age >= 18 is True, so Python goes into the inner if. has_id is False, so it takes the inner else: Show ID.",trap:"Follow the indentation: the inner else belongs to 'if has_id'."},
 {id:"l5-07",t:"l5",d:"m",ty:"fill",q:"What does this print?",code:"print(not 5 > 3)",a:["False"],tags:["predict"],
  why:"5 > 3 is True, and not flips it to False.",trap:"not is applied after the comparison is worked out."},
 {id:"l5-08",t:"l5",d:"m",ty:"mc",q:"Which condition is True only when mark is from 50 to 100, including both?",o:["mark > 50 and mark < 100","mark >= 50 or mark <= 100","mark >= 50 and mark <= 100","mark == 50 and mark == 100"],a:2,
  why:"Both limits must hold (and), and 'including' means >= and <=.",trap:"With 'or', every number passes, because every number is either >= 50 or <= 100."},
 {id:"l5-09",t:"l5",d:"m",ty:"mc",q:"What's missing from this selection flowchart?",fc:{n:[["s","term","Start",0],["i","io","Input mark",1],["d","dec","mark >= 50?",2],["y","io","Output \"Pass\"",3,1],["e","term","Stop",4]],e:[["s","i"],["i","d"],["d","y","Yes"],["y","e"]]},
  o:["A Start symbol","The No exit from the decision","An Input symbol","Nothing"],a:1,tags:["fixflow"],
  why:"Every decision needs TWO labelled exits. There's no path for when mark >= 50 is No.",trap:"Even if nothing is output for 'No', draw the No arrow joining the flow before Stop."},

 {id:"l6-04",t:"l6",d:"e",ty:"mc",q:"What does this print?",code:"for i in range(3):\n    print(i)",out:"0\n1\n2",o:["0, 1, 2 (on separate lines)","1, 2, 3 (on separate lines)","0, 1, 2, 3 (on separate lines)","3"],a:0,tags:["predict"],
  why:"range(3) starts at 0 and stops before 3: 0, 1, 2.",trap:"With one number, range starts at 0, not 1."},
 {id:"l6-05",t:"l6",d:"m",ty:"mc",q:"How many stars are printed?",code:"count = 0\nwhile count < 5:\n    print('*')\n    count = count + 2",out:"*\n*\n*",o:["2","3","5","It never stops"],a:1,tags:["predict"],
  why:"count is 0, 2, 4 when the test is True (3 stars), then 6 < 5 is False.",trap:"Write the values of count down: the step is 2, not 1."},
 {id:"l6-06",t:"l6",d:"m",ty:"fill",q:"What is the LAST number this prints?",code:"for i in range(2, 11, 3):\n    print(i)",a:["8"],tags:["predict"],
  why:"Start at 2 and add 3: 2, 5, 8. The next would be 11, but the stop value 11 is never included.",trap:"Don't print the stop value."},
 {id:"l6-07",t:"l6",d:"e",ty:"mc",q:"Which line is an ACCUMULATOR?",o:["count = count + 1","total = total + price","price = float(input())","while price != -1:"],a:1,
  why:"An accumulator adds a changing value onto a running total.",trap:"count = count + 1 adds a fixed 1 each time, so it's a counter."},
 {id:"l6-08",t:"l6",d:"e",ty:"tf",q:"range(5) gives the numbers 1, 2, 3, 4, 5.",a:false,
  why:"range(5) gives 0, 1, 2, 3, 4: five numbers, starting at 0.",trap:"For 1 to 5 use range(1, 6)."},
 {id:"l6-09",t:"l6",d:"e",ty:"order",q:"Put the parts of a while loop in the order they happen the first time.",o:["Initialise the loop control variable","Test the condition","Run the loop body","Update the loop control variable"],
  why:"Set it up, test it, do the work, change the variable, then test again.",trap:"The variable must be initialised before the first test."},
 {id:"l6-10",t:"l6",d:"m",ty:"mc",q:"Which gives exactly 10, 20, 30?",o:["range(10, 30, 10)","range(10, 31, 10)","range(10, 30)","range(1, 4)"],a:1,tags:["range"],
  why:"range(10, 31, 10) gives 10, 20, 30; the next value, 40, is past the stop.",trap:"range(10, 30, 10) stops before 30, giving only 10, 20."},
 {id:"l6-11",t:"l6",d:"m",ty:"mc",q:"What happens when this flowchart runs?",fc:{n:[["s","term","Start",0],["a","proc","count = 1",1],["d","dec","count <= 3?",2],["o","io","Output count",3],["e","term","Stop",3,1]],e:[["s","a"],["a","d"],["d","o","Yes"],["o","d"],["d","e","No"]]},
  o:["It outputs 1, 2, 3","It outputs 1 forever","It outputs nothing","It outputs 3"],a:1,tags:["fixflow"],
  why:"count is never updated, so count <= 3 stays True and it outputs 1 again and again: an infinite loop.",trap:"Add a process box 'count = count + 1' inside the loop."},

 {id:"l7-03",t:"l7",d:"e",ty:"mc",q:"A program reads customers' ages until a sentinel is entered. Which is the best sentinel?",o:["0","18","-1","25"],a:2,
  why:"No one can be -1 years old, so it can never be mistaken for real data.",trap:"0 is a real age for a baby, and 18 or 25 are common ages."},
 {id:"l7-04",t:"l7",d:"m",ty:"fill",q:"She types 4, then 6, then -1. What is printed?",code:"total = 0\nnum = int(input())\nwhile num != -1:\n    total = total + num\n    num = int(input())\nprint(total)",in:["4","6","-1"],a:["10"],tags:["predict"],
  why:"4 and 6 are added (total 10). When -1 is read, the test is False and the loop stops before adding it.",trap:"The sentinel is never processed."},
 {id:"l7-05",t:"l7",d:"e",ty:"tf",q:"In a correctly written sentinel loop, the sentinel value is added to the total.",a:false,
  why:"The sentinel only signals 'stop'. The while test catches it before it can be processed.",trap:"If your total is off by the sentinel (e.g. 1 less with -1), you read and processed in the wrong order."},
 {id:"l7-06",t:"l7",d:"h",ty:"order",q:"Put the lines of this sentinel loop in order.",o:["total = 0","num = int(input())","while num != -1:","total = total + num  (indented)","num = int(input())  (indented)","print(total)"],
  why:"Initialise, priming read, test, process, read the next value, then output after the loop.",trap:"The second input() is the LAST line inside the loop, after the processing."},
 {id:"l7-07",t:"l7",d:"e",ty:"mc",q:"What is a 'priming read'?",o:["Reading the first value before the loop starts","Reading every value twice","The last input in the loop","Printing the prompt"],a:0,
  why:"The priming read gets the first value so the while condition has something to test.",trap:"The read at the bottom of the loop gets the NEXT value; it's not the priming read."},
 {id:"l7-08",t:"l7",d:"m",ty:"mc",q:"The user types -1 straight away. What is printed on the last line?",code:"total = 0\nnum = int(input('Number (-1 to stop): '))\nwhile num != -1:\n    total = total + num\n    num = int(input('Number (-1 to stop): '))\nprint('Total:', total)",in:["-1"],o:["Total: -1","Total: 0","Nothing","An error"],a:1,tags:["predict"],
  why:"The first test, -1 != -1, is False, so the loop body never runs. total is still 0.",trap:"A while loop can run zero times."},

 /* trace-table questions: the table is generated by really running the code (tools/trace.py) */
 {id:"l4-t1",t:"l4",d:"e",ty:"trace",tr:"seq1",n:3,q:"Complete the trace table.",tags:["trace"],why:"price × qty = 25 × 3 = 75, and line 4 prints it.",trap:"Each row only shows the variable that changed on that line."},
 {id:"l4-t2",t:"l4",d:"m",ty:"trace",tr:"swap",n:4,q:"Complete the trace table for this swap.",tags:["trace"],why:"temp keeps a copy of a (5) so b can get it after a is overwritten with 9.",trap:"Without temp, both variables would end up as 9."},
 {id:"l5-t1",t:"l5",d:"e",ty:"trace",tr:"sel5",n:3,q:"Complete the trace table.",tags:["trace"],why:"120 > 100 is True, so price becomes 120 − 20 = 100, which is printed.",trap:"The print is not indented, so it runs whatever the condition gives."},
 {id:"l5-t2",t:"l5",d:"m",ty:"trace",tr:"sel2",n:4,q:"Complete the trace table. The user types 30.",tags:["trace"],why:"30 >= 33 is False; 30 >= 27 is True, so msg = 'Warm' and the else is skipped.",trap:"Once an elif is True, the later conditions are not tested at all."},
 {id:"l5-t3",t:"l5",d:"m",ty:"trace",tr:"sel4",n:3,q:"Complete the trace table.",tags:["trace"],why:"7 > 5 and 7 < 10: both True, so the 'and' is True.",trap:"Write the condition result as True or False."},
 {id:"l5-t4",t:"l5",d:"m",ty:"trace",tr:"sel3",n:3,q:"Complete the trace table for this nested if.",tags:["trace"],why:"age >= 18 is False, so the inner if is never tested and the outer else prints 'Too young'.",trap:"Only the conditions Python actually tests appear in the table."},
 {id:"l6-t1",t:"l6",d:"m",ty:"trace",tr:"for1",n:5,q:"Complete the trace table.",tags:["trace"],why:"i takes 1, 2, 3, 4 and total goes 0 → 1 → 3 → 6 → 10.",trap:"range(1, 5) stops before 5."},
 {id:"l6-t2",t:"l6",d:"e",ty:"trace",tr:"for2",n:4,q:"Complete the trace table.",tags:["trace"],why:"i is 0, 1, 2 and each time i × 2 is printed: 0, 2, 4.",trap:"range(3) starts at 0."},
 {id:"l6-t3",t:"l6",d:"m",ty:"trace",tr:"for3",n:4,q:"Complete the trace table.",tags:["trace"],why:"Start at 5, step −2: 5, 3, 1. The next would be −1, which is past the stop (0).",trap:"A negative step counts down, and the stop value is still not included."},
 {id:"l6-t4",t:"l6",d:"h",ty:"trace",tr:"for4",n:6,q:"Complete the trace table.",tags:["trace"],why:"Only the even numbers 2, 4 and 6 make n % 2 == 0 True, so count ends at 3.",trap:"% gives the remainder; an even number has remainder 0 when divided by 2."},
 {id:"l6-t5",t:"l6",d:"m",ty:"trace",tr:"for5",n:5,q:"Complete the trace table. The marks typed are 60, 75 and 90.",tags:["trace"],why:"total goes 60 → 135 → 225, then average = 225 / 3 = 75.0.",trap:"/ gives a float, so the average is 75.0, not 75."},
 {id:"l6-t6",t:"l6",d:"h",ty:"trace",tr:"for6",n:5,q:"Complete the trace table. The numbers typed are 4, 9 and 6.",tags:["trace"],why:"biggest becomes 4, then 9. 6 > 9 is False, so biggest stays 9.",trap:"biggest only changes when the condition is True."},
 {id:"l6-t7",t:"l6",d:"m",ty:"trace",tr:"while2",n:5,q:"Complete the trace table.",tags:["trace"],why:"n goes 10 → 7 → 4 → 1 → −2, and −2 > 0 is False, so −2 is printed.",trap:"When n is 1 the condition is still True, so it subtracts one more time."},
 {id:"l6-t8",t:"l6",d:"h",ty:"trace",tr:"while3",n:6,q:"Complete the trace table.",tags:["trace"],why:"balance goes 100 → 110 → 120 → 130 while years counts 1, 2, 3. 130 < 130 is False.",trap:"< does not include 130 itself."},
 {id:"l7-t1",t:"l7",d:"m",ty:"trace",tr:"sent1",n:6,q:"Complete the trace table. The user types 5, 8, 2, then -1.",tags:["trace"],why:"5, 8 and 2 are added (total 15). The -1 makes the test False before it is added.",trap:"The sentinel never reaches the total."},
 {id:"l7-t2",t:"l7",d:"m",ty:"trace",tr:"sent2",n:5,q:"Complete the trace table. The cashier types doubles, roti, then DONE.",tags:["trace"],why:"Two real items, so orders ends at 2.",trap:"DONE is the sentinel, not an order."},
 {id:"l7-t3",t:"l7",d:"h",ty:"trace",tr:"sent3",n:6,q:"Complete the trace table. The marks typed are 80, 60, then -1.",tags:["trace"],why:"count = 2, total = 140, so 140 / 2 = 70.0 is printed.",trap:"Divide by the count of real marks (2), not by 3."},

 /* ---------- COHW ---------- */
 {id:"c1-01",t:"c1",d:"e",ty:"mc",q:"Which component carries out program instructions and is often called the 'brain' of the computer?",o:["RAM","CPU","PSU","SSD"],a:1,
  why:"The CPU (central processing unit) fetches, decodes and executes instructions.",trap:"RAM holds what the CPU is working on (your desk); it doesn't do the thinking."},
 {id:"c1-02",t:"c1",d:"e",ty:"mc",q:"RAM is like your desk and storage is like your filing cabinet. What happens to what's in RAM when the PC is switched off?",o:["It's saved automatically","It's lost","It moves to the CPU","It's printed"],a:1,
  why:"RAM is volatile: it needs power to keep data. That's why you save work to storage.",trap:"Storage (SSD/HDD) keeps data with the power off. RAM does not."},
 {id:"c2-01",t:"c2",d:"m",ty:"mc",q:"Which motherboard form factor is the LARGEST?",o:["Mini-ITX","Micro-ATX","ATX","They're all the same"],a:2,
  why:"Standard ATX is 305 × 244 mm, micro-ATX is 244 × 244 mm and mini-ITX is just 170 × 170 mm.",trap:"Micro sounds small but mini-ITX is the smallest of the three."},
 {id:"c2-02",t:"c2",d:"e",ty:"mc",q:"Which slot is normally used for a graphics card?",o:["PCIe x1","PCIe x16","DIMM slot","M.2"],a:1,
  why:"Graphics cards need the most lanes, so they go in the long PCIe x16 slot.",trap:"DIMM slots are for RAM. M.2 is mostly for SSDs."},
 {id:"c2-03",t:"c2",d:"m",ty:"mc",q:"A PC beeps 3 times and won't boot. Beep codes differ between BIOS makers. What should you check FIRST to know what 3 beeps means?",o:["Reinstall Windows","The motherboard manual or maker's website","Replace the CPU","Change the monitor cable"],a:1,tags:["beep"],
  why:"The manual (or support site) lists that board's beep codes. Then you know which part to check, often RAM for memory codes.",trap:"Don't replace parts blindly. Look up the code first, then test the part it points to."},
 {id:"c3-01",t:"c3",d:"e",ty:"mc",q:"Why do you put thermal paste between the CPU and its cooler?",o:["To glue the cooler on","To fill tiny air gaps so heat moves to the cooler","To insulate the CPU from electricity","To make the fan spin"],a:1,
  why:"The metal surfaces have microscopic gaps. Paste fills them so heat transfers better than through air.",trap:"More is not better: a pea-sized amount is enough."},
 {id:"c3-02",t:"c3",d:"m",ty:"mc",q:"On an LGA socket, where are the pins?",o:["On the CPU","On the motherboard socket","On the cooler","There are no pins"],a:1,
  why:"LGA (land grid array): the pins are in the motherboard socket and the CPU has flat pads. PGA is the opposite: pins on the CPU.",trap:"Think 'L for Lands on the CPU': flat lands on the chip, pins in the socket."},
 {id:"c4-01",t:"c4",d:"e",ty:"tf",q:"A DDR4 memory stick will fit and work in a DDR5 slot.",a:false,
  why:"Each DDR generation has the notch in a different place and different voltages, so they are NOT interchangeable.",trap:"Always match the RAM generation to what the motherboard supports."},
 {id:"c4-02",t:"c4",d:"m",ty:"mc",q:"Roughly how much RAM can a 32-bit operating system use?",o:["2 GB","4 GB","16 GB","Unlimited"],a:1,
  why:"32 bits can address 2³² bytes = 4 GB. A 64-bit OS is needed to use more.",trap:"Adding 8 GB to a 32-bit OS won't help: it can only use about 4 GB (often a bit less)."},
 {id:"c5-01",t:"c5",d:"e",ty:"mc",q:"What does POST stand for?",o:["Power-On Self-Test","Primary Operating System Test","Power Output Supply Test","Processor On Startup Timer"],a:0,tags:["beep"],
  why:"POST is the Power-On Self-Test: the firmware checks the essential hardware before the OS loads.",trap:"If POST fails you'll often hear beep codes or see diagnostic lights."},
 {id:"c5-02",t:"c5",d:"m",ty:"mc",q:"A PC keeps losing its date and time every time it's unplugged. What's the most likely fix?",o:["Replace the CMOS battery","Add more RAM","Update the GPU driver","Replace the hard drive"],a:0,
  why:"The small coin battery on the motherboard keeps the real-time clock (and settings) running when the PC has no power.",trap:"Wrong time after unplugging is the classic sign of a dead CMOS battery."},
 {id:"c6-01",t:"c6",d:"m",ty:"mc",q:"Which PSU voltage rail powers the CPU and graphics card?",o:["3.3 V","5 V","12 V","240 V"],a:2,
  why:"The 12 V rail feeds the power-hungry parts: CPU (via the 8-pin connector) and GPU (via PCIe 6+2 connectors).",trap:"3.3 V and 5 V are for smaller loads. 240 V is wall power going INTO the PSU."},
 {id:"c7-01",t:"c7",d:"m",ty:"mc",q:"Which RAID level stripes data across disks with NO redundancy?",o:["RAID 0","RAID 1","RAID 5","RAID 10"],a:0,
  why:"RAID 0 splits data across disks for speed. If one disk dies, everything is lost.",trap:"The 0 is a reminder: zero protection."},
 {id:"c7-02",t:"c7",d:"m",ty:"tf",q:"Every M.2 SSD uses NVMe.",a:false,
  why:"M.2 is just the shape and slot. An M.2 drive can be SATA or NVMe, and the motherboard must support the type.",trap:"Don't confuse the form factor (M.2) with the interface (SATA or NVMe)."},
 {id:"c7-03",t:"c7",d:"m",ty:"tf",q:"RAID 1 (mirroring) means you don't need a backup.",a:false,
  why:"RAID protects against a drive failing, but if you delete a file or get ransomware, the mirror copies the damage too.",trap:"RAID is NOT a backup. Keep a separate copy."},
 {id:"c8-01",t:"c8",d:"m",ty:"mc",q:"What is the maximum speed of USB 2.0?",o:["12 Mbps","480 Mbps","5 Gbps","40 Gbps"],a:1,
  why:"USB 2.0 (Hi-Speed) runs at up to 480 Mbps. USB 3.x starts at 5 Gbps.",trap:"40 Gbps is Thunderbolt 3/4 or USB4."},
 {id:"c9-01",t:"c9",d:"e",ty:"mc",q:"Which video port carries digital video AND audio and is found on almost every TV?",o:["VGA","DVI","HDMI","PS/2"],a:2,
  why:"HDMI carries digital video and audio in one cable.",trap:"VGA is analogue and video-only. DVI is mostly video-only."},
 {id:"c10-01",t:"c10",d:"m",ty:"mc",q:"Which describes a Type 2 hypervisor?",o:["Runs directly on the hardware","Runs as an app on top of a host OS, like VirtualBox","Is the same as a BIOS","Can only run Linux"],a:1,
  why:"Type 2 (hosted) hypervisors such as VirtualBox run on top of Windows/macOS/Linux. Type 1 (bare-metal) runs straight on the hardware.",trap:"Type 1 = bare metal (closest to hardware). Type 2 = on top of an OS."},
 {id:"c12-01",t:"c12",d:"h",ty:"order",q:"Put the laser printing process in order.",o:["Processing","Charging","Exposing","Developing","Transferring","Fusing","Cleaning"],
  why:"Processing → Charging → Exposing → Developing → Transferring → Fusing → Cleaning.",trap:"Fusing (heat and pressure melting toner onto the paper) comes after transferring the toner."},
 {id:"c13-01",t:"c13",d:"e",ty:"mc",q:"T&TEC power goes out. Which device keeps the PC running for a few minutes so you can save and shut down?",o:["Surge suppressor","UPS","Line conditioner","Power strip"],a:1,
  why:"A UPS (uninterruptible power supply) has a battery that takes over instantly when mains power fails.",trap:"A surge suppressor only blocks spikes. It has no battery."},
];
